import{MOVEMENT_VISUALS,SURFACE_VISUALS}from'./movement-visuals.js';
import{setCellRenderRoles}from'./render-intent.js';
import {NATIVE_PRIORITIES} from './native-priority.js';
import {RULES,movementAt,setMovement,createMovementQuery} from './world-model.js';
import {sourceBlock} from './source-cells.js';

export function movementPanel(api,state,target,close=()=>{}){
 const $=s=>target.querySelector(s),esc=api.esc;
 target.innerHTML=`<p class="hint-line">Each rule has a matching coloured icon and map overlay. Gold marks encounter grass; purple marks Walk behind; green marks ordinary walkable tiles. These colours show the walking rule; foreground artwork is checked separately. Imported collision and height are available immediately. Paint a correction to override an object's default footprint; Keep ROM rule restores automatic behaviour.</p><p class="hint-line">Encounter grass is walkable and uses native grass effects. Set its Pokémon in Workshop → Game data → Wild Pokémon. Test battles in Play edited ROM; Quick check tests movement only.</p><div class="rule-presets">${Object.entries(MOVEMENT_VISUALS).map(([id,r])=>`<button data-rule="${id}" data-movement-rule="${id}" type="button" style="--rule:${r.color}" class="${state.rule===id?'active':''}" aria-pressed="${state.rule===id}"><span class="rule-icon" aria-hidden="true">${r.icon}</span>${r.name}</button>`).join('')}</div><p class="hint-line">Surface effects · choose one, then Paint rules onto the tiles you want. Choosing an effect does not change the whole map. P = reflective puddle, W = reflective pond, S = splashes, F = footprints.</p><div class="rule-presets">${Object.entries(SURFACE_VISUALS).map(([id,r])=>`<button data-surface="${id}" type="button" style="--rule:${r.color}" class="${state.behavior===+id?'active':''}" aria-pressed="${state.behavior===+id}"><span class="rule-icon" aria-hidden="true">${r.icon}</span>${r.name}</button>`).join('')}</div><label>Native surface effect<select id="nativeSurface"><option value="">Choose surface…</option>${Object.entries(SURFACE_VISUALS).map(([id,r])=>`<option value="${id}" ${state.behavior===+id?'selected':''}>${r.icon} · ${r.name}</option>`).join('')}</select></label><p class="hint-line">Native effects depend on the engine, tileset and available field sprites. These presets use FRLG behavior IDs; use matching sources. Quick check does not render reflections.</p><label class="check"><input id="toolboxRulesOverlay" type="checkbox" ${state.overlay?'checked':''}> Show movement overlay</label><div class="field-row"><label>Display<select id="movementDisplay">${[['rules','Walking rules'],['collision','Native collision · 0–3'],['elevation','Elevation · 0–15'],['behavior','Tile behaviour']].map(([id,n])=>`<option value="${id}" ${(state.overlayType||'rules')===id?'selected':''}>${n}</option>`).join('')}</select></label><label>Opacity<input id="movementOpacity" type="range" min="10" max="90" value="${Math.round((state.overlayOpacity??.45)*100)}"></label></div><details><summary>Native values and height</summary><label>Elevation<select id="movementHeight"><option value="">Keep existing</option>${Array.from({length:16},(_,i)=>`<option value="${i}" ${state.elevation===i?'selected':''}>${i}${i===3?' · ordinary ground':i===1?' · water':''}</option>`).join('')}</select></label><label>Collision<select id="movementCollision"><option value="">Use selected rule</option>${[0,1,2,3].map(n=>`<option value="${n}" ${state.collision===n?'selected':''}>${n}${n?' · blocked':' · passable'}</option>`).join('')}</select></label><label>Behaviour · optional native ID<input id="movementBehavior" type="number" min="0" max="511" value="${state.behavior??''}" placeholder="Use selected rule"></label></details><div class="toolbox-actions"><button id="useMovementBrush" type="button" class="primary">Paint rules</button><button id="movementArea" type="button">Rectangle</button><button id="movementFill" type="button">Fill matching</button><button id="movementInspect" type="button">Inspect tile</button></div><label class="check"><input id="autoMovementDefaults" type="checkbox" ${api.map().autoCollision!==false?'checked':''}> Apply automatic rules to newly painted artwork</label><p class="hint-line">Trees and tall props use a solid base with upper artwork behind the player. NPCs and HM objects keep their native collision.</p>`;
 target.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>{state.rule=b.dataset.rule;state.collision=null;state.behavior=null;if(state.rule==='original')state.elevation=null;movementPanel(api,state,target,close);});
 const chooseSurface=value=>{if(!SURFACE_VISUALS[value])return;state.rule=+value===16?'water':'walk';state.behavior=+value;state.collision=0;state.elevation=+value===16?1:3;movementPanel(api,state,target,close);};$('#nativeSurface').onchange=e=>chooseSurface(e.target.value);target.querySelectorAll('[data-surface]').forEach(b=>b.onclick=()=>chooseSurface(b.dataset.surface));
 $('#toolboxRulesOverlay').onchange=e=>{state.overlay=e.target.checked;api.refresh();};$('#movementDisplay').onchange=e=>{state.overlayType=e.target.value;state.overlay=true;api.refresh();};$('#movementOpacity').oninput=e=>{state.overlayOpacity=+e.target.value/100;state.overlay=true;api.draw?.();};
 for(const [id,key]of [['movementHeight','elevation'],['movementCollision','collision'],['movementBehavior','behavior']])$('#'+id).onchange=e=>state[key]=e.target.value===''?null:+e.target.value;
 $('#autoMovementDefaults').onchange=e=>{api.change(()=>api.map().autoCollision=e.target.checked);};
 for(const [id,tool]of [['useMovementBrush','rules'],['movementArea','rulesRect'],['movementFill','rulesFill'],['movementInspect','inspect']])$('#'+id).onclick=()=>{state.overlay=true;api.mode(tool);close();api.refresh();};
}
export function movementBrush(state){if(state.rule==='grass')return{mode:'walk',collision:0,elevation:3,behavior:2,overrideObjects:true,...Object.fromEntries(['elevation','collision','behavior'].filter(k=>state[k]!==null&&state[k]!==undefined).map(k=>[k,state[k]]))};return {mode:state.rule==='original'&&['elevation','collision','behavior'].some(k=>state[k]!==null&&state[k]!==undefined)?'walk':state.rule,overrideObjects:true,...Object.fromEntries(['elevation','collision','behavior'].filter(k=>state[k]!==null&&state[k]!==undefined).map(k=>[k,state[k]]))};}
export function inspectMovement(api,x,y){
 const map=api.map(),r=movementAt(map,x,y),word=sourceBlock(map,x,y),esc=api.esc;
 api.modal('Tile '+x+', '+y,`<p>${esc(map.name)} · ${word===undefined?'New tile':'Source metatile #'+(word&1023)}</p><div class="studio-metrics"><span><b>${r.collision}</b>collision</span><span><b>${r.elevation}</b>elevation</span></div>${r.layerType!==null&&r.layerType!==undefined?`<p>Native priority: ${NATIVE_PRIORITIES[r.layerType]||'Unknown'}. ${r.nativeForeground?'Upper native artwork can cover the player.':'Native artwork uses the lower backgrounds.'}</p>`:''}<label>Walking rule<select id="tileRule">${Object.entries(RULES).map(([id,v])=>`<option value="${id}" ${(r.mode==='original'?(r.behind?'behind':r.behavior===16?'water':r.collision?'block':'walk'):r.mode)===id?'selected':''}>${v.name}</option>`).join('')}</select></label><div class="field-row"><label>Native collision<input id="tileCollision" type="number" min="0" max="3" value="${r.collision}"></label><label>Elevation<input id="tileHeight" type="number" min="0" max="15" value="${r.elevation}"></label></div><label>Native behaviour<input id="tileBehavior" type="number" min="0" max="511" value="${r.behavior??((map.rom?.attributes?.[word&1023]||0)&511)}"></label><fieldset><legend>Visual layers · independent of walking</legend>${['ground','details','objects','overhead'].filter(k=>map.layers[k]?.[y*map.width+x]).map(k=>`<label>${({ground:'Ground / floor',details:'Behind / detail',objects:'Object artwork',overhead:'Foreground'})[k]}<select id="tileRender_${k}">${(k==='ground'?['ground']:['behind','foreground']).map(v=>`<option value="${v}" ${(map.layers[k][y*map.width+x].renderRole||(k==='ground'?'ground':k==='overhead'||r.nativeForeground?'foreground':'behind'))===v?'selected':''}>${v==='ground'?'Ground · always below player':v==='behind'?'Behind · below player':'Foreground · above player'}</option>`).join('')}</select></label>`).join('')}<p class="hint-line">Player-level depth sorting uses native NPC/event sprites. Object pixel masks stay with the object; collision and elevation are saved separately.</p></fieldset><button id="tileRestore" type="button">Restore artwork / ROM defaults</button><p class="hint-line">Manual values override ordinary object footprints on this tile. NPCs and native HM objects remain solid.</p>`,()=>{
  const $=s=>document.querySelector(s),collision=+$('#tileCollision').value,elevation=+$('#tileHeight').value,behavior=+$('#tileBehavior').value;
  if(![collision,elevation,behavior].every(Number.isInteger)||collision<0||collision>3||elevation<0||elevation>15||behavior<0||behavior>511)throw Error('Use valid native collision, height and behaviour values.');
  api.change(()=>{setMovement(map,x,y,{mode:$('#tileRule').value,collision,elevation,behavior,overrideObjects:true});setCellRenderRoles(map,x,y,Object.fromEntries(['ground','details','objects','overhead'].filter(k=>$('#tileRender_'+k)).map(k=>[k,$('#tileRender_'+k).value])));});api.refresh();
 },'Save tile');
 document.querySelector('#tileRestore').onclick=()=>{api.change(()=>setMovement(map,x,y,{mode:'original'}));api.close();api.refresh();};
 document.querySelector('#tileRule').onchange=e=>{const mode=e.target.value;document.querySelector('#tileCollision').value=mode==='block'||mode.startsWith('ledge_')?1:0;document.querySelector('#tileBehavior').value=mode==='water'?16:0;};
}
export function fillMovement(map,x,y,rule){
 const query=createMovementQuery(map),key=r=>[r.collision,r.elevation,r.behavior].join(':'),match=key(query(x,y)),seen=new Uint8Array(map.width*map.height),todo=[y*map.width+x],cells=[];
 while(todo.length){const i=todo.pop();if(seen[i])continue;seen[i]=1;const xx=i%map.width,yy=Math.floor(i/map.width);if(key(query(xx,yy))!==match)continue;cells.push(i);if(xx)todo.push(i-1);if(xx+1<map.width)todo.push(i+1);if(yy)todo.push(i-map.width);if(yy+1<map.height)todo.push(i+map.width);}
 for(const i of cells)setMovement(map,i%map.width,Math.floor(i/map.width),rule);
 return cells.length;
}
